"""FinalAgent: bargains in SUPPLIER-VALUE space with lever bundles, not on unit price.

Why: the supplier prices every sheet by what it is worth to it in cash (price at its standard terms, minus
the cost of the payment days we ask), and terms such as contract months, lead time or an index clause are
free for it. So we (1) fix the VALUE we offer each round, (2) pick the lever combination that is cheapest
for US at that value (long payment, short lead time, ...), and set the price that gives exactly that value.
- Value schedule: anchor at 0.76 x the value of their sheet, then close 55% of the gap, then jump to the
  fixed point of "their ask falls by g x our rise" (g estimated, default 0.25): the ask freezes at a random
  early round, so two big moves beat ten small steps. A sheet above their value x (1 - tol) is accepted at
  our price, so we only go above it in the last two messages.
- Sheets: the lowest-C bundle, the lowest-C bundle with payment <= their standard (suppliers that refuse
  long terms), their own terms re-priced (pure price move). Cheapest for us first: they take the first of equal value.
- Closing: a supplier sheet meets us when its C is no more than our cheapest sheet's C.
- A silent thread is skipped after `max_asks` messages; never walk away while a supplier is alive.
"""

import itertools
import math

from ..cost import closing_terms, complete_offer, must_haves_ok, supplier_value, total_cost
from ..docs import standard_terms
from ..guard import satisfy_must_haves
from ..play import ENDED, closing_move, latest, live_threads, moves_left
from .reciprocal import (
    ReciprocalAgent,
    _c_alt,
    _live,
    _mine,
    _pinned,
    _sup,
    _tick,
    _valid,
    case_c_open,
    closing_accept,
)
from .reciprocal import _sheets as their_sheets

QUOTE_ASK = "Could you please send us your quote?"
BODY = (
    "Thank you for your offer. Please find our proposal in the attached term sheets; each of them works for us, "
    "please pick the one that suits you best."
)
R_SUP, STD_PD, TOL = 0.074, 30, 0.012  # fitted median supplier rate, its payment days, tolerance
ANCHOR, JUMP = 0.76, 0.55
G_DEFAULT, G_MIN, G_MAX, MIN_STEP = 0.25, 0.1, 0.8, 0.01
MAX_COMBOS, MAX_SHEETS = 3000, 3


def _priced(case, events, std):
    """[(C, sheet)] of the thread's standing sheets, must-haves ignored."""
    return _valid(case, events, std, math.inf, musts=False)


def _std_full(case, events):
    """The supplier's complete standard terms: its quote PDF, its payment days (default 30), gaps from the plan."""
    std = standard_terms(events)
    pd = std.get("payment_days") or STD_PD
    full = closing_terms(case, {"unit_price": None}, std)
    full = {**full, **{k: v for k, v in std.items() if v is not None}, "payment_days": pd}
    return full


def _value(case, std_full, terms):
    return supplier_value(case, terms, {"standard": std_full, "interest_rate": R_SUP})


def _lowest_value(case, std_full, sheets):
    vals = [_value(case, std_full, s["terms"]) for s in sheets if (s.get("terms") or {}).get("unit_price") is not None]
    return min(vals, default=None)


def _target(case, events, std_full):
    """The value (to the supplier) we offer this round, or None without a priced sheet of theirs."""
    theirs = [_lowest_value(case, std_full, m["term_sheets"]) for m in _sup(events) if m.get("term_sheets")]
    theirs = [v for v in theirs if v is not None]
    if not theirs:
        return None
    a = theirs[-1]
    mine = [m["term_sheets"][0]["terms"] for m in _mine(events) if m.get("term_sheets")]
    ours = [_value(case, std_full, t) for t in mine if t.get("unit_price")]
    tick = _tick(a)
    if not ours:
        o = ANCHOR * a
    elif len(ours) == 1:
        o = ours[-1] + JUMP * (a - ours[-1])
    else:
        g = G_DEFAULT
        if len(theirs) >= 2 and (fall := theirs[-2] - theirs[-1]) > 0 and (rise := ours[-1] - ours[-2]) > 0:
            g = min(G_MAX, max(G_MIN, fall / rise))
        o_star = (1 - TOL) * (a + g * ours[-1]) / (1 + g * (1 - TOL))
        o = min(a - tick, max(o_star, ours[-1] + max(MIN_STEP * a, tick)))
    if moves_left(case, events) <= 2:
        o = a - tick
    return max(o, ours[-1]) if ours else o


def _pins(events):
    """Pinned fields: the parent's, plus an index clause the supplier repeated twice while we asked otherwise."""
    pins = _pinned(events)
    sup = [m["term_sheets"][0]["terms"] for m in _sup(events) if m.get("term_sheets")]
    mine = [m for m in _mine(events) if m.get("term_sheets")]
    if len(sup) >= 2 and mine and "index_clause" in sup[-1] and sup[-1]["index_clause"] == sup[-2].get("index_clause"):
        if any(s["terms"].get("index_clause") != sup[-1]["index_clause"] for s in mine[-1]["term_sheets"]):
            pins["index_clause"] = sup[-1]["index_clause"]
    return pins


def _reduce(opts, centre, k):
    """At most k options: the one at `centre`, the extremes, then the closest to it."""
    if len(opts) <= k:
        return opts
    nums = all(isinstance(o, int | float) and not isinstance(o, bool) for o in opts)
    if not nums:
        return opts[:k]
    keep = {min(opts), max(opts)} | ({centre} if centre in opts else set())
    rest = sorted((o for o in opts if o not in keep), key=lambda o: (abs(o - (centre if centre is not None else o)), o))
    return sorted(keep | set(rest[: max(0, k - len(keep))]))


class FinalAgent(ReciprocalAgent):
    def __init__(self, anchor=ANCHOR, max_asks=2):
        self.anchor, self.max_asks = anchor, max_asks

    def _ask(self, case, sid):
        return {"supplier_id": sid, "message": {"subject": case.get("title", "Our enquiry"), "body": QUOTE_ASK}}

    def _unheard(self, threads):
        """A thread that never answered and has had fewer than max_asks of our messages, or None."""
        return next((s for s, ev in threads.items() if not _sup(ev) and len(_mine(ev)) < self.max_asks), None)

    def _close(self, case, quoted):
        """Accept the best acceptable sheet; else rescue a priced sheet that only breaks a must-have by
        sending it with the must-haves fixed; else walk away (only when nothing else can be done)."""
        if not live_threads(quoted):
            return {"supplier_id": next(iter(quoted), None), "message": {"action": {"type": "walk_away"}}}
        move = closing_move(case, quoted)
        if move["message"].get("action", {}).get("type") != "walk_away":
            return move
        c_alt, c_open, best = _c_alt(case), case_c_open(case, quoted), None
        for sid, ev in quoted.items():
            if latest(ev).get("status") in ENDED or moves_left(case, ev) < 1:
                continue
            std = standard_terms(ev)
            base = {k: std[k] for k in case["negotiable"] if k in std}
            sent = [x["terms"] for m in _mine(ev) for x in m.get("term_sheets") or []]
            for _, sh in _priced(case, ev, std):
                fixed = complete_offer(case, satisfy_must_haves(case, {**base, **sh["terms"]}, std))
                if not must_haves_ok(case, fixed, std) or fixed in sent:
                    continue
                if (c := total_cost(case, fixed, std)) < c_alt and c <= c_open:
                    best = min(best or (c, sid, fixed), (c, sid, fixed), key=lambda x: x[0])
        if best is None:
            return move
        _, sid, fixed = best
        body = "We can accept your price with the terms below; please confirm."
        message = {"subject": case.get("title", "Our proposal"), "body": body, "term_sheets": [{"terms": fixed}]}
        return {"supplier_id": sid, "message": message}

    def decide(self, case, threads):
        quoted = {s: ev for s, ev in threads.items() if _sup(ev)}
        if not _live(threads):  # nothing to answer: ask a thread that never wrote, else give up
            if (sid := self._unheard(threads)) is not None:
                return self._ask(case, sid)
            return {"supplier_id": next(iter(threads), None), "message": {"action": {"type": "walk_away"}}}
        if accept := closing_accept(case, quoted, by_cost=True):
            return accept
        live = [s for s in _live(threads) if moves_left(case, threads[s]) >= 1]
        open_ = [s for s in live if latest(threads[s]).get("status") not in ("final_offer", "agreed")]

        def silent(s):  # no priced sheet and already asked enough: skip it, never walk away from it
            ev = threads[s]
            return not _priced(case, ev, standard_terms(ev)) and len(_mine(ev)) >= self.max_asks

        open_ = [s for s in open_ if not silent(s)]
        if not open_:
            if (sid := self._unheard(threads)) is not None:
                return self._ask(case, sid)
            return self._close(case, quoted)

        def key(s):  # keep every thread moving: fewest messages first, then the cheapest
            ev = threads[s]
            c = min((c for c, _ in _priced(case, ev, standard_terms(ev))), default=math.inf)
            return len(_mine(ev)), c

        sid = min(open_, key=key)
        events = threads[sid]
        if moves_left(case, events) <= 1:  # our last message must never be a counter that can time out
            return self._close(case, quoted)
        std = standard_terms(events)
        # a must-have breach is fixed in our sheet
        valid = _valid(case, events, std, math.inf) or _priced(case, events, std)
        if not valid:  # no priced sheet to answer: ask for one
            return self._ask(case, sid)
        _, best = min(valid, key=lambda v: v[0])
        sheets = self._sheets(case, events, std, best["terms"])
        if not sheets:  # nothing new left to offer: close on the best sheet, or give up
            return self._close(case, quoted)
        return {
            "supplier_id": sid,
            "message": {
                "subject": case.get("title", "Our proposal"),
                "body": BODY,
                "term_sheets": [{"terms": t} for t in sheets],
            },
        }

    def _sheets(self, case, events, std, theirs):
        std_full = _std_full(case, events)
        o = _target(case, events, std_full)
        if o is None:
            return []
        a = _lowest_value(case, std_full, their_sheets(events))
        pins, c_alt, tick = _pins(events), _c_alt(case), _tick(a)
        levers = [f for f in case["negotiable"] if f != "unit_price"]
        centre = {f: theirs.get(f, std_full.get(f)) for f in levers}
        options = []
        for f in levers:
            if f in pins:
                options.append([pins[f]])
            else:
                options.append(list((case.get("term_options") or {}).get(f) or [centre[f]]))
        k = 4
        while math.prod(len(x) for x in options) > MAX_COMBOS and k > 1:
            options = [_reduce(x, centre[f], k) for f, x in zip(levers, options, strict=True)]
            k -= 1
        seen = [s["terms"] for m in _mine(events) if m.get("term_sheets") for s in m["term_sheets"]]
        priced = []  # (combo without price, value at price 0, value per euro of price)
        for vals in itertools.product(*options):
            combo = satisfy_must_haves(case, dict(zip(levers, vals, strict=True)), std_full)
            v0 = _value(case, std_full, {**combo, "unit_price": 0.0})
            b = _value(case, std_full, {**combo, "unit_price": 1.0}) - v0
            if b > 0:
                priced.append((combo, v0, b))
        own = {f: std_full[f] for f in case["negotiable"] if f in std_full}
        own.update({k: v for k, v in theirs.items() if v is not None})
        own.update(pins)
        v0 = _value(case, std_full, {**own, "unit_price": 0.0})
        own_b = _value(case, std_full, {**own, "unit_price": 1.0}) - v0

        def ok(t):
            return t["unit_price"] > 0 and must_haves_ok(case, t, std_full) and total_cost(case, t, std_full) < c_alt

        def build(value):
            cands = []
            for combo, c0, b in priced:
                t = {**combo, "unit_price": round((value - c0) / b, 2)}
                if ok(t):
                    cands.append((total_cost(case, t, std_full), t))
            out = []
            if cands:
                out.append(min(cands, key=lambda x: x[0])[1])
                short = [x for x in cands if (x[1].get("payment_days") or 0) <= std_full["payment_days"]]
                if short:
                    out.append(min(short, key=lambda x: x[0])[1])
            if own_b > 0:
                t = satisfy_must_haves(case, {**own, "unit_price": round((value - v0) / own_b, 2)}, std_full)
                if ok(t):
                    out.append(t)
            done = []
            for t in out:
                if (c := complete_offer(case, t)) not in done:
                    done.append(c)
            return done

        sheets = build(o)
        while sheets and sheets[0] in seen and o < a:
            o += tick
            sheets = build(o)
        if not sheets or sheets[0] in seen:
            return []
        return [t for i, t in enumerate(sheets) if i == 0 or t not in seen][:MAX_SHEETS]

"""The Reciprocal Bargainer: moves a visible step every round, in step with the supplier, and closes.

Why (30 real practice runs): suppliers answer visible moves with moves and send `final_offer` when
we idle (anchors ~20% below their price that then crept 0.01-0.03 a round scored 0.03-0.1), while an
agent that moved +2-3 EUR every round scored 0.94. And one run lost a 28.00 / 30 d / lead 35 deal
(best, must-have met) by re-asking for 90 days until the supplier walked: score 0.

- `closing_accept` (reusable; `ClosingAgent(delegate)` adds it to any agent): evaluate EVERY sheet of
  every live thread (alternatives `offer:..-a` too) with total_cost; take the cheapest that keeps the
  must-haves, beats the case alternative and is no worse than the thread's opening quote; accept it
  when the supplier says final_offer/agreed, or met our last price, or repeated itself (after >= 3 of
  our messages), or it is our last allowed message.
- `ReciprocalAgent`: anchor at 0.80 x their best standing price (0.75 floor, never above our current
  price when they ask for more), then every round close 25% (rising by 5 points a round, cap 50%) of the
  gap to their best standing price, at least 1% of price (while they move: at most 0.25 x their last
  move, at least 0.2%: the local simulator pays for patience, real suppliers for visible steps), but not closer than 3% to it before the last
  two messages (the supplier then ends with final_offer and we accept); never the same sheet twice; two sheets per
  message (main: the best contract length, payment and index option we may ask; variant: their own
  payment / index terms at the same price).
"""

import logging
import math
import re

from ..cost import complete_offer, must_haves_ok, total_cost
from ..docs import standard_terms
from ..guard import satisfy_must_haves
from ..play import ENDED, closing_move, latest, moves_left, standing

log = logging.getLogger("arena")

ANCHOR, ANCHOR_FLOOR = 0.80, 0.75  # first offer: x their best standing price (0.90 was met at once in 3 real runs)
FRAC0, FRAC_STEP, FRAC_MAX, MIN_STEP = 0.25, 0.05, 0.50, 0.01
KEEP = 0.05  # stay this far below their price until the last two messages (they end with final_offer, we accept)
MOVING_MIN = 0.002  # smallest step (x price) while they move; MIN_STEP when they hold still
MATCH = 0.25  # while they move, our step is at most this x their last move
REPEAT_AFTER = 3  # our messages before "the supplier repeated its sheet twice" means it has stalled
LIMIT = re.compile(r"(?:limit|stick to|only with|stay at|must stay|have to)[^.\n]{0,40}?(\d+)\s*days", re.I)
PAYMENT = re.compile(r"\b(?:payment|net|zahlungsziel)\b", re.I)
SENTENCE = re.compile(r"[.!?\n](?!\d)")  # not the point of 28.00
PINNABLE = ("payment_days", "lead_time_days", "contract_months")


def _tick(price):
    """The smallest visible price step: a cent, or 0.1% of the price when prices are large (per 100 / 1000 pieces)."""
    return max(0.01, 0.001 * price)


def _sup(events):
    return [m for m in events if m.get("from") != "buyer"]


def _mine(events):
    return [m for m in events if m.get("from") == "buyer"]


def _sheets(events):
    """Sheets of the supplier's newest message that has any (look back past question-only replies)."""
    return next((m["term_sheets"] for m in reversed(_sup(events)) if m.get("term_sheets")), [])


def _live(threads):
    """Threads with a supplier message that have not ended."""
    return [s for s, ev in threads.items() if _sup(ev) and latest(ev).get("status") not in ENDED]


def _c_alt(case):
    alt = (case["buyer"].get("alternative") or {}).get("terms") or {}
    return total_cost(case, alt) if alt.get("unit_price") else math.inf


def case_c_open(case, threads):
    """C of the best opening: the cheapest first-message sheet (alternatives too) of ANY thread, ended
    ones included, that keeps the must-haves. A deal must beat it: a deal worse than the opening scores 0."""
    out = math.inf
    for ev in threads.values():
        first = next((m["term_sheets"] for m in _sup(ev) if m.get("term_sheets")), [])
        std = standard_terms(ev)
        for s in first:
            t = s.get("terms") or {}
            if t.get("unit_price") is not None and must_haves_ok(case, t, std):
                out = min(out, total_cost(case, t, std))
    return out


def _valid(case, events, std, c_alt, musts=True):
    """[(C, sheet)] of the thread's standing sheets that keep the must-haves (unless musts=False), beat the alternative."""
    out = []
    for s in _sheets(events):
        t = s.get("terms") or {}
        if t.get("unit_price") is not None and s.get("term_sheet_id") and (not musts or must_haves_ok(case, t, std)):
            if (c := total_cost(case, t, std)) < c_alt:
                out.append((c, s))
    return out


def _ready(case, events, sheet, by_cost=False):
    if latest(events).get("status") in ("final_offer", "agreed") or moves_left(case, events) <= 1:
        return True
    mine = [m for m in _mine(events) if m.get("term_sheets")]
    if not mine:
        return False
    if by_cost:  # lever bundles: they met us when their sheet costs us no more than our cheapest sheet
        std = standard_terms(events)
        ours = min(total_cost(case, s["terms"], std) for s in mine[-1]["term_sheets"])
        if total_cost(case, sheet["terms"], std) <= ours + 0.01:
            return True  # they met us
    else:
        price = sheet["terms"]["unit_price"]
        if price <= max(s["terms"].get("unit_price") or 0 for s in mine[-1]["term_sheets"]):
            return True  # they met us
    sup = [[s["terms"] for s in m["term_sheets"]] for m in _sup(events) if m.get("term_sheets")]
    return len(mine) >= REPEAT_AFTER and len(sup) >= 2 and sup[-1] == sup[-2]  # every sheet repeated, alternatives too


def _copy_sheet(case, events, std, sheet):
    """Our own term sheet with exactly the terms of one of theirs (to make it the standing sheet)."""
    base = {k: std[k] for k in case["negotiable"] if k in std}
    return complete_offer(case, {**base, **sheet["terms"]})


def _all_heard(case, threads):
    """Several live suppliers: each has had 2 of our messages, or is final / agreed, or is nearly out of messages."""
    live = _live(threads)
    return len(live) < 2 or all(
        len(_mine(threads[s])) >= 2 or latest(threads[s]).get("status") in ("final_offer", "agreed") or moves_left(case, threads[s]) <= 1
        for s in live
    )


def closing_accept(case, threads, c_open=None, by_cost=False):
    """The decision that closes on the cheapest acceptable sheet when the rule says so, else None: an accept of
    the thread's standing sheet, or, when the best sheet is another one (an alternative `-a`, or one before a
    question-only reply), our term sheet with its exact terms - the supplier then agrees on a standing sheet."""
    c_alt, best, order = _c_alt(case), None, {s: i for i, s in enumerate(threads)}
    if not _all_heard(case, threads):
        return None
    c_open = case_c_open(case, threads) if c_open is None else c_open
    for sid in _live(threads):
        ev = threads[sid]
        for c, s in _valid(case, ev, standard_terms(ev), c_alt):
            if s["term_sheet_id"] != standing(ev)[0] and moves_left(case, ev) <= 1:
                continue  # our last message: only a standing sheet can still be accepted (a copy would be swapped away)
            if c < c_open:
                cand = (c, order[sid], sid, s["term_sheet_id"])  # ties: the thread that arrived first
                best = min(best or cand, cand)
    if best is None:
        return None
    _, _, sid, sheet_id = best
    events = threads[sid]
    sheet = next(s for s in _sheets(events) if s["term_sheet_id"] == sheet_id)
    if not _ready(case, events, sheet, by_cost):
        return None
    if sheet_id == standing(events)[0]:
        return {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": sheet_id}}}
    copy = _copy_sheet(case, events, standard_terms(events), sheet)
    if any(s["terms"] == copy for m in _mine(events) for s in m.get("term_sheets") or []):
        return None  # sent already and not agreed: let the agent carry on
    return {"supplier_id": sid, "message": {"subject": case.get("title", "Our proposal"), "body": "We accept these terms; please confirm.", "term_sheets": [{"terms": copy}]}}


class ClosingAgent:
    """Adds only the accept rule to any agent."""

    def __init__(self, delegate):
        self.delegate = delegate

    def __getattr__(self, name):
        if name == "delegate":
            raise AttributeError(name)
        return getattr(self.delegate, name)

    def decide(self, case, threads):
        try:
            if accept := closing_accept(case, threads):
                return accept
        except Exception:
            log.exception("%s closing rule failed", case.get("case_id"))
        return self.delegate.decide(case, threads)


def _pinned(events):
    """Terms the supplier will not move: repeated by it twice while we asked otherwise, or stated as a limit."""
    pins = {}
    sup = [m["term_sheets"][0]["terms"] for m in _sup(events) if m.get("term_sheets")]
    mine = [m for m in _mine(events) if m.get("term_sheets")]
    if len(sup) >= 2 and mine:
        for f in PINNABLE:
            asked = {s["terms"].get(f) for s in mine[-1]["term_sheets"]} - {None, sup[-1].get(f)}
            if sup[-1].get(f) is not None and sup[-1].get(f) == sup[-2].get(f) and asked:
                pins[f] = sup[-1][f]
    for m in _sup(events)[-2:]:
        for sentence in SENTENCE.split(m.get("body") or ""):
            if (hit := LIMIT.search(sentence)) and PAYMENT.search(sentence):
                pins["payment_days"] = int(hit.group(1))
    return pins


class ReciprocalAgent:
    def decide(self, case, threads):
        if not _live(threads):  # nothing to answer
            return {"supplier_id": next(iter(threads), None), "message": {"action": {"type": "walk_away"}}}
        if accept := closing_accept(case, threads):
            return accept
        live = [s for s in _live(threads) if moves_left(case, threads[s]) >= 1]
        open_ = [s for s in live if latest(threads[s]).get("status") not in ("final_offer", "agreed")]
        if not open_:
            return closing_move(case, threads)

        def key(s):  # keep every thread moving: fewest messages first, then the cheapest
            ev = threads[s]
            c = min((c for c, _ in _valid(case, ev, standard_terms(ev), math.inf, musts=False)), default=math.inf)
            return len(_mine(ev)), c

        sid = min(open_, key=key)
        events = threads[sid]
        std = standard_terms(events)
        valid = _valid(case, events, std, math.inf) or _valid(case, events, std, math.inf, musts=False)  # a must-have breach is fixed in our sheet
        if not valid:  # no priced sheet to answer: ask for one, give up after 3 asks
            if len(_mine(events)) >= 3:
                return {"supplier_id": sid, "message": {"action": {"type": "walk_away"}}}
            return {"supplier_id": sid, "message": {"subject": case.get("title", "Our enquiry"), "body": "Could you please send us your quote?"}}
        _, best = min(valid, key=lambda v: v[0])
        sheets = self._sheets(case, events, std, best["terms"])
        if not sheets:  # nothing new left to offer: close on the best sheet, or give up
            return closing_move(case, threads)
        return {
            "supplier_id": sid,
            "message": {
                "subject": case.get("title", "Our proposal"),
                "body": "Thank you for your offer. We have moved on our side; please see our updated terms.",
                "term_sheets": [{"terms": t} for t in sheets],
            },
        }

    @staticmethod
    def _their_move(events):
        """How far the supplier's best price fell in its last message (0 if it did not)."""
        ps = [min(s["terms"]["unit_price"] for s in m["term_sheets"] if s["terms"].get("unit_price") is not None)
              for m in _sup(events) if any(s["terms"].get("unit_price") is not None for s in m["term_sheets"])]
        return max(0.0, ps[-2] - ps[-1]) if len(ps) >= 2 else 0.0

    def _price(self, case, events, p):
        mine = [m["term_sheets"][0]["terms"]["unit_price"] for m in _mine(events) if m.get("term_sheets") and m["term_sheets"][0]["terms"].get("unit_price")]
        if not mine:
            cur = case["buyer"].get("current_unit_price") or p
            return max(ANCHOR_FLOOR * p, min(ANCHOR * p, cur))  # anchor; never pay more than now unless forced
        frac = min(FRAC_MAX, FRAC0 + FRAC_STEP * len(mine))
        move = self._their_move(events)
        step = max(frac * (p - mine[-1]), MIN_STEP * p, _tick(p))
        if move > 0:  # they moved: answer in step, not beyond (a supplier that holds still gets the full step)
            step = max(MOVING_MIN * p, _tick(p), min(step, MATCH * move))
        top = p if moves_left(case, events) <= 2 else p * (1 - KEEP)
        return max(mine[-1], min(top, mine[-1] + step))

    @staticmethod
    def _index_variant(case, main, p, opts, pins, make, cost, cap, seen):
        """An index clause is security for the supplier, not cash: offer it for the price at which our C is just
        below the main sheet's C (the clause's expected cost per unit taken off the price). None if not negotiable."""
        if "index_clause" not in case["negotiable"] or "index_clause" in pins:
            return None
        best = None
        for clause in (c for c in opts.get("index_clause", []) if c):
            t = make(main["unit_price"], index_clause=clause, **{f: main[f] for f in ("payment_days", "contract_months") if f in main})
            if t["index_clause"] != clause or t["index_clause"] == main.get("index_clause"):
                continue
            slope = cost({**t, "unit_price": t["unit_price"] + 1}) - cost(t)
            if slope <= 0:
                continue
            price = round(max(0.75 * p, min(p, t["unit_price"] - (cost(t) - cost(main)) / slope - 0.01)), 2)  # no lowball
            v = cap({**t, "unit_price": price})
            if 0 < price and v not in seen and cost(v) < cost(main) and (best is None or v["unit_price"] > best["unit_price"]):
                best = v
